/* ═══════════════════════════════════════
   HELPERS
═══════════════════════════════════════ */
function uid(){ return Math.random().toString(36).slice(2,9); }
function fmt(s){ return `${String(Math.floor(s/60)).padStart(2,"0")}:${String(s%60).padStart(2,"0")}`; }
function rand(arr){ return arr[Math.floor(Math.random()*arr.length)]; }

function load(key, def) {
  try { const v=localStorage.getItem(key); return v!=null?JSON.parse(v):def; } catch{ return def; }
}
function save(key, val) {
  try { localStorage.setItem(key, JSON.stringify(val)); } catch{}
}

/* ═══════════════════════════════════════
   WEB AUDIO — calming tones via AudioContext
═══════════════════════════════════════ */
function useAudio() {
  const ctxRef = useRef(null);
  const volRef = useRef(load("cp_vol", 0.5));
  const onRef  = useRef(load("cp_sound", true));

  function getCtx(){
    if(!ctxRef.current) ctxRef.current = new (window.AudioContext||window.webkitAudioContext)();
    return ctxRef.current;
  }

  // Play a gentle chime: one or more sine tones fade in/out
  function chime(freqs=[523, 659, 784], dur=1.8){
    if(!onRef.current) return;
    try {
      const ctx = getCtx();
      if(ctx.state === "suspended") ctx.resume();
      freqs.forEach((f,i)=>{
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain); gain.connect(ctx.destination);
        osc.type = "sine";
        osc.frequency.value = f;
        const t = ctx.currentTime + i*0.12;
        gain.gain.setValueAtTime(0, t);
        gain.gain.linearRampToValueAtTime(volRef.current * 0.22, t+0.08);
        gain.gain.exponentialRampToValueAtTime(0.001, t+dur);
        osc.start(t); osc.stop(t+dur+0.05);
      });
    } catch(e){}
  }

  // Soft star earned: warm ascending tones
  function chimeStar(){ chime([659,784,1047], 2.0); }
  // Reward complete: full chord
  function chimeReward(){ chime([523,659,784,1047], 2.5); }
  // Transition done: gentle resolution
  function chimeTransition(){ chime([784,659,523], 1.5); }
  // Activity tick warning: single soft tone
  function chimeWarn(){ chime([440], 0.9); }

  function setVol(v){ volRef.current=v; save("cp_vol",v); }
  function setOn(v){ onRef.current=v; save("cp_sound",v); }
  function getVol(){ return volRef.current; }
  function getOn(){ return onRef.current; }

  return { chime, chimeStar, chimeReward, chimeTransition, chimeWarn, setVol, setOn, getVol, getOn };
}

/* ═══════════════════════════════════════
   TIMER HOOK
   timerPhase: "green" | "yellow" | "red"
   green  = >50% remaining
   yellow = ≤50% and > (30s or 10%)
   red    = ≤30s OR ≤10% remaining
═══════════════════════════════════════ */
function useTimer(totalSecs){
  const [rem,setRem]=useState(totalSecs);
  const [running,setRunning]=useState(false);
  const ref=useRef(null);
  useEffect(()=>{setRem(totalSecs);setRunning(false);},[totalSecs]);
  useEffect(()=>{
    if(running&&rem>0){
      ref.current=setInterval(()=>setRem(r=>{
        if(r<=1){clearInterval(ref.current);setRunning(false);return 0;}
        return r-1;
      }),1000);
    } else clearInterval(ref.current);
    return()=>clearInterval(ref.current);
  },[running]);
  const done=rem===0&&totalSecs>0;
  const prog=totalSecs>0?rem/totalSecs:1;
  const warn=totalSecs>0&&rem<=60&&rem>0;
  // Traffic-light phase — fixed thresholds regardless of total duration:
  // green  = >50% remaining
  // yellow = ≤50% and >10 seconds remaining
  // red    = ≤10 seconds remaining
  let timerPhase="green";
  if(totalSecs>0&&rem>0){
    if(rem<=10)        timerPhase="red";
    else if(prog<0.5)  timerPhase="yellow";
  }
  if(done) timerPhase="red";
  return{
    rem,running,done,prog,warn,timerPhase,
    start:()=>rem>0&&setRunning(true),
    pause:()=>setRunning(false),
    reset:()=>{setRunning(false);setRem(totalSecs);},
    restart:()=>{setRem(totalSecs);setRunning(true);},
  };
}

/* ═══════════════════════════════════════
   SVG RING
═══════════════════════════════════════ */
function Ring({prog,color,size=160,sw=10,bg="rgba(0,0,0,0.07)",children}){
  const r=(size-sw*2)/2, circ=2*Math.PI*r;
  const offset=circ*(1-Math.max(0,Math.min(1,prog)));
  return(
    <div style={{position:"relative",width:size,height:size,flexShrink:0}}>
      <svg width={size} height={size} style={{transform:"rotate(-90deg)",position:"absolute",inset:0}}>
        <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={bg} strokeWidth={sw}/>
        <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={color} strokeWidth={sw}
          strokeLinecap="round" strokeDasharray={circ} strokeDashoffset={offset}
          style={{transition:"stroke-dashoffset 1s linear",filter:`drop-shadow(0 0 8px ${color}88)`}}/>
      </svg>
      <div style={{position:"absolute",inset:0,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center"}}>
        {children}
      </div>
    </div>
  );
}

