function Chip({activity,index}){
  function onDragStart(e){
    dragState.activityId=activity.id;
    dragState.sourceIndex=null;
    e.dataTransfer.setData("activityId",activity.id);
    e.dataTransfer.effectAllowed="copy";
  }
  return(
    <div
      draggable onDragStart={onDragStart}
      style={{
        display:"flex",flexDirection:"column",alignItems:"center",gap:5,
        padding:"12px 8px",borderRadius:14,
        background:C.surface,border:`1.5px solid ${C.border}`,
        boxShadow:"0 1px 6px rgba(0,0,0,.06)",
        cursor:"grab",userSelect:"none",
        transition:"transform .15s,box-shadow .15s",
        animationDelay:`${(index||0)*0.02}s`,
      }}
      onMouseOver={e=>{e.currentTarget.style.transform="translateY(-2px) scale(1.04)";e.currentTarget.style.boxShadow="0 6px 18px rgba(0,0,0,.12)";}}
      onMouseOut={e=>{e.currentTarget.style.transform="";e.currentTarget.style.boxShadow="0 1px 6px rgba(0,0,0,.06)";}}
    >
      <span style={{fontSize:26,lineHeight:1}}>{activity.emoji}</span>
      <span style={{fontSize:10,fontWeight:700,color:C.ink,lineHeight:1.2,textAlign:"center"}}>{activity.label}</span>
    </div>
  );
}

/* ═══════════════════════════════════════
   DURATION PICKER  (minutes + seconds)
   totalSeconds is stored; display as m:ss
═══════════════════════════════════════ */
const ACTIVITY_PRESETS=[5,10,15,20,30,45,60]; // minutes

function DurationPicker({totalSeconds,onChange,color,light}){
  const [open,setOpen]=useState(false);
  const wrapRef=useRef(null);

  // close on click outside
  useEffect(()=>{
    if(!open) return;
    function handler(e){ if(wrapRef.current&&!wrapRef.current.contains(e.target)) setOpen(false); }
    document.addEventListener("mousedown",handler);
    return()=>document.removeEventListener("mousedown",handler);
  },[open]);

  // derive display values from stored totalSeconds (may be null)
  const storedMins  = totalSeconds!=null ? Math.floor(totalSeconds/60) : "";
  const storedSecs  = totalSeconds!=null ? totalSeconds%60 : "";

  // local editing state (strings so user can clear field)
  const [cMin,setCMin]=useState(storedMins!==null?String(storedMins):"");
  const [cSec,setCSec]=useState(storedSecs!==null?String(storedSecs):"");

  // keep local state in sync if parent resets
  useEffect(()=>{
    setCMin(totalSeconds!=null?String(Math.floor(totalSeconds/60)):"");
    setCSec(totalSeconds!=null?String(totalSeconds%60):"");
  },[totalSeconds]);

  function commit(m,s){
    const mins=parseInt(m)||0;
    const secs=parseInt(s)||0;
    const total=mins*60+secs;
    if(total>0) onChange(total);
  }

  function handlePreset(mins){
    setOpen(false);
    onChange(mins*60);
  }

  // label shown on the row
  const label = totalSeconds>0
    ? (storedSecs>0 ? `${storedMins}m ${storedSecs}s` : `${storedMins}m`)
    : null;

  const acColor=color||C.teal;
  const acLight=light||C.tealL;

  return(
    <div ref={wrapRef} style={{position:"relative",flexShrink:0}}>
      <div style={{display:"flex",gap:4,alignItems:"center",flexWrap:"wrap"}}>
        {/* Preset pills */}
        {ACTIVITY_PRESETS.map(m=>{
          const active=totalSeconds===m*60;
          return(
            <button key={m} onClick={()=>handlePreset(m)} style={{
              padding:"3px 7px",borderRadius:10,fontSize:10,fontWeight:700,cursor:"pointer",
              border:`1.5px solid ${active?acColor:C.border}`,
              background:active?acLight:C.bgAlt,
              color:active?acColor:C.muted,
              transition:"all .12s",
            }}>{m}m</button>
          );
        })}

        {/* Custom toggle */}
        <button onClick={()=>setOpen(o=>!o)} style={{
          padding:"3px 9px",borderRadius:10,fontSize:10,fontWeight:700,cursor:"pointer",
          border:`1.5px solid ${open?acColor:C.border}`,
          background:open?acLight:C.bgAlt,
          color:open?acColor:C.muted,
          transition:"all .12s",
        }}>
          {label&&!open ? `✎ ${label}` : "✎ Custom"}
        </button>
      </div>

      {/* Custom panel — drops down */}
      {open&&(
        <div style={{
          position:"absolute",top:"calc(100% + 6px)",right:0,zIndex:200,
          background:C.surface,border:`1.5px solid ${acColor}55`,
          borderRadius:14,padding:"12px 14px",
          boxShadow:"0 8px 24px rgba(0,0,0,0.12)",
          display:"flex",flexDirection:"column",gap:10,
          minWidth:200,animation:"cpPop .2s ease both",
        }}>
          <div style={{fontSize:11,fontWeight:800,color:acColor,letterSpacing:"0.05em"}}>Set Custom Duration</div>
          <div style={{display:"flex",gap:8,alignItems:"center"}}>
            {/* Minutes */}
            <div style={{display:"flex",flexDirection:"column",gap:3,flex:1}}>
              <label style={{fontSize:10,fontWeight:700,color:C.muted}}>Minutes</label>
              <div style={{display:"flex",alignItems:"center",gap:4}}>
                <button onClick={()=>{const v=Math.max(0,(parseInt(cMin)||0)-1);setCMin(String(v));}} style={{
                  width:24,height:24,borderRadius:6,border:`1px solid ${C.border}`,
                  background:C.bgAlt,fontSize:14,cursor:"pointer",display:"flex",
                  alignItems:"center",justifyContent:"center",fontFamily:FONT,
                }}>−</button>
                <input
                  type="number" min="0" max="180"
                  value={cMin}
                  onChange={e=>setCMin(e.target.value)}
                  onBlur={()=>commit(cMin,cSec)}
                  style={{
                    width:52,padding:"4px 6px",borderRadius:8,textAlign:"center",
                    border:`1.5px solid ${acColor}66`,background:C.surface,
                    fontSize:14,fontWeight:700,color:C.ink,outline:"none",fontFamily:FONT,
                  }}
                />
                <button onClick={()=>{const v=(parseInt(cMin)||0)+1;setCMin(String(v));}} style={{
                  width:24,height:24,borderRadius:6,border:`1px solid ${C.border}`,
                  background:C.bgAlt,fontSize:14,cursor:"pointer",display:"flex",
                  alignItems:"center",justifyContent:"center",fontFamily:FONT,
                }}>+</button>
              </div>
            </div>

            <div style={{fontSize:18,fontWeight:800,color:C.muted,marginTop:14}}>:</div>

            {/* Seconds */}
            <div style={{display:"flex",flexDirection:"column",gap:3,flex:1}}>
              <label style={{fontSize:10,fontWeight:700,color:C.muted}}>Seconds</label>
              <div style={{display:"flex",alignItems:"center",gap:4}}>
                <button onClick={()=>{const v=Math.max(0,(parseInt(cSec)||0)-5);setCSec(String(v));}} style={{
                  width:24,height:24,borderRadius:6,border:`1px solid ${C.border}`,
                  background:C.bgAlt,fontSize:14,cursor:"pointer",display:"flex",
                  alignItems:"center",justifyContent:"center",fontFamily:FONT,
                }}>−</button>
                <input
                  type="number" min="0" max="59"
                  value={cSec}
                  onChange={e=>setCSec(e.target.value)}
                  onBlur={()=>commit(cMin,cSec)}
                  style={{
                    width:52,padding:"4px 6px",borderRadius:8,textAlign:"center",
                    border:`1.5px solid ${acColor}66`,background:C.surface,
                    fontSize:14,fontWeight:700,color:C.ink,outline:"none",fontFamily:FONT,
                  }}
                />
                <button onClick={()=>{const v=Math.min(59,(parseInt(cSec)||0)+5);setCSec(String(v));}} style={{
                  width:24,height:24,borderRadius:6,border:`1px solid ${C.border}`,
                  background:C.bgAlt,fontSize:14,cursor:"pointer",display:"flex",
                  alignItems:"center",justifyContent:"center",fontFamily:FONT,
                }}>+</button>
              </div>
            </div>
          </div>

          {/* Quick second presets */}
          <div>
            <div style={{fontSize:10,fontWeight:700,color:C.muted,marginBottom:5}}>Quick seconds</div>
            <div style={{display:"flex",gap:4,flexWrap:"wrap"}}>
              {[0,15,30,45].map(s=>(
                <button key={s} onClick={()=>{setCSec(String(s));commit(cMin,s);}} style={{
                  padding:"3px 8px",borderRadius:8,fontSize:10,fontWeight:700,cursor:"pointer",
                  border:`1px solid ${parseInt(cSec)===s?acColor:C.border}`,
                  background:parseInt(cSec)===s?acLight:C.bgAlt,
                  color:parseInt(cSec)===s?acColor:C.muted,
                }}>{s}s</button>
              ))}
            </div>
          </div>

          {/* Set button */}
          <button
            onClick={()=>{commit(cMin,cSec);setOpen(false);}}
            style={{
              padding:"7px",borderRadius:10,border:"none",cursor:"pointer",
              background:`linear-gradient(135deg,${acColor},${acColor}CC)`,
              color:"white",fontSize:12,fontWeight:800,fontFamily:FONT,
            }}>
            Set {(parseInt(cMin)||0) > 0 || (parseInt(cSec)||0) > 0
              ? `${parseInt(cMin)||0}m ${parseInt(cSec)||0}s`
              : "Duration"} ✓
          </button>
        </div>
      )}
    </div>
  );
}

/* ═══════════════════════════════════════
   SCHEDULE BUILDER
═══════════════════════════════════════ */
function DropLine({active,onDragOver,onDragEnter,onDragLeave,onDrop}){
  return(
    <div onDragOver={onDragOver} onDragEnter={onDragEnter} onDragLeave={onDragLeave} onDrop={onDrop}
      style={{
        height:active?36:10,borderRadius:8,
        background:active?C.tealL:"transparent",
        border:active?`2px dashed ${C.teal}`:"2px dashed transparent",
        display:"flex",alignItems:"center",justifyContent:"center",
        transition:"all .15s",marginBottom:active?4:0,
        fontSize:11,color:C.teal,fontWeight:700,
      }}
    >{active&&"✦ Drop here"}</div>
  );
}

function ScheduleBuilder({items,onAddItem,onRemoveItem,onChangeDuration,onReorder,currentIndex}){
  const [dropTarget,setDropTarget]=useState(null);

  function handleDrop(e,insertIndex){
    e.preventDefault();e.stopPropagation();setDropTarget(null);
    const{activityId,sourceIndex}=dragState;
    if(sourceIndex!==null) onReorder(sourceIndex,insertIndex);
    else if(activityId){
      const a=ACTIVITIES.find(x=>x.id===activityId);
      if(a) onAddItem(a,insertIndex);
    }
    dragState.activityId=null;dragState.sourceIndex=null;
  }

  function handleDragOver(e){e.preventDefault();e.dataTransfer.dropEffect=dragState.sourceIndex!==null?"move":"copy";}

  if(items.length===0){
    return(
      <div onDragOver={handleDragOver} onDragEnter={()=>setDropTarget(0)} onDragLeave={()=>setDropTarget(null)}
        onDrop={e=>handleDrop(e,0)}
        style={{
          padding:"48px 20px",textAlign:"center",borderRadius:16,
          border:`2px dashed ${dropTarget===0?C.teal:C.border}`,
          background:dropTarget===0?C.tealL:C.bgAlt,
          color:C.muted,fontSize:13,fontWeight:600,transition:"all .15s",
        }}>
        <div style={{fontSize:32,marginBottom:10}}>📋</div>
        <div>Drag activities here to build your day</div>
        <div style={{fontSize:11,marginTop:6,opacity:0.6}}>Add as many as you need — the schedule rotates automatically</div>
      </div>
    );
  }

  return(
    <div style={{display:"flex",flexDirection:"column",width:"100%"}}>
      <DropLine active={dropTarget===0} onDragOver={handleDragOver}
        onDragEnter={()=>setDropTarget(0)} onDragLeave={()=>setDropTarget(null)}
        onDrop={e=>handleDrop(e,0)}/>
      {items.map((item,i)=>{
        const isDone=i<currentIndex;
        const isNow=i===currentIndex;
        const isNext=i===currentIndex+1;
        const isThen=i===currentIndex+2;
        const badgeColor=isNow?C.teal:isNext?C.sun:isThen?C.sky:C.bgAlt;        const badgeText=isNow?"NOW":isNext?"NXT":isThen?"THN":`${i+1}`;
        return(
          <div key={item.uid}>
            <div
              draggable
              onDragStart={e=>{dragState.activityId=item.activity.id;dragState.sourceIndex=i;e.dataTransfer.effectAllowed="move";}}
              onDragEnd={()=>{dragState.activityId=null;dragState.sourceIndex=null;}}
              style={{
                display:"flex",alignItems:"center",gap:10,
                padding:"9px 12px",borderRadius:12,
                border:`1.5px solid ${isNow?C.teal+"55":C.border}`,
                background:isDone?"rgba(0,0,0,0.03)":isNow?C.tealL:C.surface,
                marginBottom:2,cursor:"grab",
                opacity:isDone?0.45:1,
                transition:"all .2s",
              }}>
              <div style={{color:C.muted,fontSize:14,flexShrink:0,cursor:"grab",userSelect:"none"}}>⠿</div>
              <div style={{
                width:30,height:30,borderRadius:9,flexShrink:0,
                background:isDone?C.bgAlt:badgeColor,
                color:isDone?C.muted:i<3?"white":C.muted,
                display:"flex",alignItems:"center",justifyContent:"center",
                fontSize:i<3?8:11,fontWeight:900,
              }}>{isDone?"✓":badgeText}</div>
              <span style={{fontSize:20,lineHeight:1,flexShrink:0}}>{item.activity.emoji}</span>
              <div style={{flex:1,fontSize:13,fontWeight:700,color:isDone?C.muted:C.ink,
                textDecoration:isDone?"line-through":"none"}}>{item.activity.label}</div>
              <div style={{flexShrink:0,position:"relative"}}>
                <DurationPicker
                  totalSeconds={item.totalSeconds}
                  onChange={secs=>onChangeDuration(item.uid,secs)}
                  color={item.activity.color}
                  light={item.activity.light}
                />
              </div>
              <button onClick={()=>onRemoveItem(item.uid)} style={{
                width:26,height:26,borderRadius:"50%",
                border:`1.5px solid ${C.border}`,background:C.bgAlt,
                color:C.muted,fontSize:13,flexShrink:0,cursor:"pointer",
                display:"flex",alignItems:"center",justifyContent:"center",
              }}>✕</button>
            </div>
            <DropLine active={dropTarget===i+1} onDragOver={handleDragOver}
              onDragEnter={()=>setDropTarget(i+1)} onDragLeave={()=>setDropTarget(null)}
              onDrop={e=>handleDrop(e,i+1)}/>
          </div>
        );
      })}
    </div>
  );
}

/* ═══════════════════════════════════════
   STAR BAR (display header)
═══════════════════════════════════════ */
function StarBar({earned,goal,reward}){
  return(
    <div style={{display:"flex",alignItems:"center",gap:10,padding:"8px 16px",borderRadius:20,
      background:"rgba(255,255,255,0.9)",backdropFilter:"blur(12px)",
      border:`1.5px solid ${C.border}`,boxShadow:"0 2px 12px rgba(0,0,0,0.06)"}}>
      <span style={{fontSize:12,fontWeight:800,color:C.goldD}}>⭐</span>
      <div style={{display:"flex",gap:3}}>
        {Array.from({length:goal},(_,i)=>(
          <div key={i} style={{
            fontSize:i<earned?20:16,opacity:i<earned?1:0.22,
            filter:i<earned?"drop-shadow(0 0 4px #F5C30099)":"none",
            transition:"all 0.4s ease",
          }}>⭐</div>
        ))}
      </div>
      <div style={{fontSize:11,fontWeight:700,color:C.goldD,background:C.goldL,
        padding:"2px 10px",borderRadius:20,border:`1px solid ${C.gold}55`,whiteSpace:"nowrap"}}>
        {earned}/{goal} → {reward}
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════
   DISPLAY ACTIVITY CARD
═══════════════════════════════════════ */
function DisplayCard({item,role,timer}){
  const meta={
    now:{label:"NOW",color:C.teal,light:C.tealL,dark:C.tealD},
    next:{label:"NEXT",color:C.sun,light:C.sunL,dark:C.sunD},
    then:{label:"THEN",color:C.sky,light:C.skyL,dark:C.skyD},
  }[role];
  const isNow=role==="now";
  const ringColor=timer?(timer.done?C.sage:meta.color):meta.color;

  return(
    <div style={{
      flex:isNow?1.25:1,borderRadius:32,
      background:isNow?`linear-gradient(150deg,${item?.activity.light||meta.light},${C.surface})`:C.surface,
      border:`2.5px solid ${isNow?(item?.activity.color||meta.color)+"44":C.border}`,
      boxShadow:isNow?`0 20px 56px ${(item?.activity.color||meta.color)}28,0 2px 8px rgba(0,0,0,0.04)`:"0 4px 18px rgba(0,0,0,0.05)",
      display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",
      padding:"28px 20px",gap:12,position:"relative",overflow:"hidden",
      animation:`cpPop .45s cubic-bezier(.34,1.3,.64,1) ${role==="next"?.08:role==="then"?.16:0}s both`,
    }}>
      <div style={{fontSize:isNow?13:10,fontWeight:800,letterSpacing:"0.14em",textTransform:"uppercase",
        color:meta.color,background:meta.light,padding:"4px 14px",borderRadius:20,
        border:`1px solid ${meta.color}33`}}>{meta.label}</div>
      {item?(
        <>
          <div style={{fontSize:isNow?80:52,lineHeight:1,
            animation:isNow?"cpBreathe 5s ease-in-out infinite":"none",
            filter:isNow?"drop-shadow(0 4px 14px rgba(0,0,0,0.10))":"none"}}>
            {item.activity.emoji}
          </div>
          <div style={{fontFamily:SERIF,fontSize:isNow?44:26,fontWeight:isNow?600:400,
            color:C.ink,textAlign:"center",letterSpacing:"-0.5px",lineHeight:1.1}}>
            {item.activity.label}
          </div>
          {item.totalSeconds>0&&(
            <div style={{fontSize:12,fontWeight:700,color:isNow?meta.dark:meta.color,
              background:meta.light,padding:"3px 12px",borderRadius:20,
              border:`1px solid ${meta.color}33`}}>
              {item.totalSeconds%60>0
                ?`${Math.floor(item.totalSeconds/60)}m ${item.totalSeconds%60}s`
                :`${Math.floor(item.totalSeconds/60)}m`}
            </div>
          )}
        </>
      ):(
        <div style={{fontSize:14,color:C.muted,fontStyle:"italic",textAlign:"center",padding:"8px 0"}}>
          {role==="then"?"End of day flow 🌅":"Nothing scheduled"}
        </div>
      )}
      {isNow&&timer&&item&&(
        <Ring prog={timer.prog} color={ringColor} size={110} sw={8} bg="rgba(0,0,0,0.07)">
          <div style={{fontFamily:FONT,fontSize:timer.done?20:24,fontWeight:800,
            color:timer.done?C.sage:C.ink,
            letterSpacing:"-1px",lineHeight:1,
            animation:timer.done?"cpBounce .6s ease":"none"}}>
            {timer.done?"✓":fmt(timer.rem)}
          </div>
          {timer.done&&<div style={{fontSize:10,color:C.sage,fontWeight:700,marginTop:2}}>Done!</div>}
        </Ring>
      )}
      {isNow&&item&&(
        <div style={{position:"absolute",bottom:-60,right:-60,width:180,height:180,borderRadius:"50%",
          background:`radial-gradient(circle,${item.activity.color}18 0%,transparent 70%)`,
          pointerEvents:"none"}}/>
      )}
    </div>
  );
}

/* ═══════════════════════════════════════
   SCHEDULE TEMPLATES
   Stored as cp_templates: [{id,name,items}]
   Each item: {uid, activity:{id,...}, totalSeconds}
═══════════════════════════════════════ */
function TemplatesPanel({schedItems,onLoadTemplate,onClose}){
  const [templates,setTemplates]=useState(()=>load("cp_templates",[]));
  const [saveName,setSaveName]=useState("");
  const [saved,setSaved]=useState(false);

  function persist(t){ setTemplates(t); save("cp_templates",t); }

  function handleSave(){
    if(!saveName.trim()||schedItems.length===0) return;
    const stripped=schedItems.map(({uid:_,...rest})=>({...rest,uid:uid()}));
    const entry={id:uid(),name:saveName.trim(),items:stripped,createdAt:Date.now()};
    persist([entry,...templates]);
    setSaveName("");
    setSaved(true);
    setTimeout(()=>setSaved(false),1800);
  }

  function handleDelete(id){ persist(templates.filter(t=>t.id!==id)); }

  function handleLoad(tmpl){
    // Re-stamp UIDs so loaded items are fresh
    const fresh=tmpl.items.map(item=>({...item,uid:uid()}));
    onLoadTemplate(fresh);
    onClose();
  }

  return(
    <div style={{padding:"16px 24px",background:"#F0F7FF",
      borderBottom:`1.5px solid ${C.sky}44`,
      animation:"cpSlideDown .3s ease both"}}>

      {/* Save current schedule */}
      <div style={{marginBottom:16}}>
        <div style={{fontSize:11,fontWeight:800,color:C.skyD,marginBottom:8}}>
          📋 Save Current Schedule as Template
        </div>
        <div style={{display:"flex",gap:8,alignItems:"center"}}>
          <input
            value={saveName}
            onChange={e=>setSaveName(e.target.value)}
            onKeyDown={e=>e.key==="Enter"&&handleSave()}
            placeholder={schedItems.length===0?"Add activities first…":"e.g. Monday, A-Day, Short Day…"}
            disabled={schedItems.length===0}
            style={{flex:1,padding:"7px 12px",borderRadius:10,
              border:`1.5px solid ${C.sky}66`,background:"white",
              fontSize:12,fontFamily:FONT,outline:"none",
              opacity:schedItems.length===0?0.5:1}}/>
          <button
            onClick={handleSave}
            disabled={!saveName.trim()||schedItems.length===0}
            style={{
              padding:"7px 16px",borderRadius:10,border:"none",cursor:"pointer",
              background:(!saveName.trim()||schedItems.length===0)?"rgba(0,0,0,0.08)":`linear-gradient(135deg,${C.sky},${C.skyD})`,
              color:(!saveName.trim()||schedItems.length===0)?C.muted:"white",
              fontSize:12,fontWeight:700,fontFamily:FONT,transition:"all .15s",
            }}>
            {saved?"✓ Saved!":"Save"}
          </button>
        </div>
        {schedItems.length===0&&(
          <div style={{fontSize:10,color:C.muted,marginTop:5}}>
            Build a schedule above, then save it as a reusable template.
          </div>
        )}
      </div>

      {/* Saved templates list */}
      {templates.length===0?(
        <div style={{fontSize:12,color:C.muted,fontStyle:"italic",textAlign:"center",padding:"8px 0"}}>
          No templates yet — save your first schedule above
        </div>
      ):(
        <div>
          <div style={{fontSize:11,fontWeight:800,color:C.skyD,marginBottom:8}}>
            Saved Templates ({templates.length})
          </div>
          <div style={{display:"flex",flexDirection:"column",gap:6,maxHeight:220,overflowY:"auto"}}>
            {templates.map(t=>(
              <div key={t.id} style={{
                display:"flex",alignItems:"center",gap:10,
                padding:"9px 14px",borderRadius:12,
                background:"rgba(255,255,255,0.9)",border:`1.5px solid ${C.sky}44`,
              }}>
                <div style={{flex:1}}>
                  <div style={{fontSize:13,fontWeight:700,color:C.ink}}>{t.name}</div>
                  <div style={{fontSize:11,color:C.muted,marginTop:1}}>
                    {t.items.length} activit{t.items.length===1?"y":"ies"} · {
                      t.items.filter(i=>i.totalSeconds>0).length > 0
                        ? `${Math.round(t.items.reduce((s,i)=>s+(i.totalSeconds||0),0)/60)}m total`
                        : "no durations set"
                    }
                  </div>
                </div>
                <button onClick={()=>handleLoad(t)} style={{
                  padding:"5px 14px",borderRadius:10,border:"none",cursor:"pointer",
                  background:`linear-gradient(135deg,${C.sky},${C.skyD})`,
                  color:"white",fontSize:11,fontWeight:700,fontFamily:FONT,
                }}>Load →</button>
                <button onClick={()=>handleDelete(t.id)} style={{
                  width:28,height:28,borderRadius:"50%",cursor:"pointer",
                  border:`1.5px solid ${C.border}`,background:C.bgAlt,
                  color:C.muted,fontSize:12,display:"flex",alignItems:"center",justifyContent:"center",
                }}>✕</button>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/* ═══════════════════════════════════════
   CUSTOM ACTIVITY CREATOR
   Stored as cp_custom: [{id,label,emoji,color,light}]
═══════════════════════════════════════ */
const COLOR_OPTIONS=[
  {color:C.teal,   light:C.tealL,  label:"Teal"  },
  {color:C.sky,    light:C.skyL,   label:"Blue"  },
  {color:C.sun,    light:C.sunL,   label:"Gold"  },
  {color:C.sage,   light:C.sageL,  label:"Green" },
  {color:C.peach,  light:C.peachL, label:"Peach" },
  {color:C.rose,   light:C.roseL,  label:"Rose"  },
  {color:C.lavender,light:C.lavL,  label:"Purple"},
];

function CustomActivityCreator({onAdd,onClose}){
  const [emoji,setEmoji]=useState("⭐");
  const [label,setLabel]=useState("");
  const [colorIdx,setColorIdx]=useState(0);
  const [emojiInput,setEmojiInput]=useState(false);

  function handleAdd(){
    if(!label.trim()) return;
    const chosen=COLOR_OPTIONS[colorIdx];
    onAdd({
      id:"custom_"+uid(),
      label:label.trim(),
      emoji,
      color:chosen.color,
      light:chosen.light,
      custom:true,
    });
    setLabel("");setEmoji("⭐");setColorIdx(0);
    onClose();
  }

  // Quick emoji suggestions
  const EMOJI_SUGGESTIONS=["⭐","🎯","🏆","💡","🔥","🌟","📖","✍️","🎲","🧩","🎭","🌈","🚀","💎","🎪","🦋","🌻","🎸","🏅","💪"];

  return(
    <div style={{
      padding:"14px 12px",borderTop:`1.5px solid ${C.border}`,
      background:C.bgAlt,animation:"cpSlideUp .25s ease both",
    }}>
      <div style={{fontSize:11,fontWeight:800,color:C.teal,marginBottom:10,letterSpacing:"0.05em"}}>
        ✨ Create Custom Activity
      </div>

      {/* Emoji picker */}
      <div style={{marginBottom:8}}>
        <div style={{fontSize:10,fontWeight:700,color:C.muted,marginBottom:5}}>Emoji</div>
        <div style={{display:"flex",gap:4,flexWrap:"wrap",marginBottom:5}}>
          {EMOJI_SUGGESTIONS.map(e=>(
            <button key={e} onClick={()=>{setEmoji(e);setEmojiInput(false);}} style={{
              width:28,height:28,borderRadius:7,border:`1.5px solid ${emoji===e?C.teal:C.border}`,
              background:emoji===e?C.tealL:"white",fontSize:15,cursor:"pointer",
              display:"flex",alignItems:"center",justifyContent:"center",
            }}>{e}</button>
          ))}
        </div>
        <div style={{display:"flex",alignItems:"center",gap:6}}>
          <span style={{fontSize:10,color:C.muted,fontWeight:600}}>Or type one:</span>
          <input
            value={emojiInput?emoji:""}
            onChange={e=>{
              const val=e.target.value;
              // grab last grapheme cluster — works for most emoji
              const chars=[...val];
              if(chars.length>0){setEmoji(chars[chars.length-1]);setEmojiInput(true);}
            }}
            placeholder="😀"
            style={{width:44,padding:"3px 6px",borderRadius:7,textAlign:"center",
              border:`1.5px solid ${C.border}`,background:"white",fontSize:16,
              fontFamily:FONT,outline:"none"}}/>
          <span style={{fontSize:20,lineHeight:1}}>{emoji}</span>
        </div>
      </div>

      {/* Title */}
      <div style={{marginBottom:8}}>
        <div style={{fontSize:10,fontWeight:700,color:C.muted,marginBottom:5}}>Activity Name</div>
        <input
          value={label}
          onChange={e=>setLabel(e.target.value)}
          onKeyDown={e=>e.key==="Enter"&&handleAdd()}
          placeholder="e.g. Guided Reading, STEM Lab…"
          style={{width:"100%",padding:"6px 10px",borderRadius:8,
            border:`1.5px solid ${C.border}`,background:"white",
            fontSize:12,fontFamily:FONT,color:C.ink,outline:"none"}}/>
      </div>

      {/* Color */}
      <div style={{marginBottom:10}}>
        <div style={{fontSize:10,fontWeight:700,color:C.muted,marginBottom:5}}>Color</div>
        <div style={{display:"flex",gap:5}}>
          {COLOR_OPTIONS.map((c,i)=>(
            <button key={i} onClick={()=>setColorIdx(i)} style={{
              width:22,height:22,borderRadius:"50%",cursor:"pointer",
              background:c.color,border:`2.5px solid ${colorIdx===i?"white":c.color}`,
              boxShadow:colorIdx===i?`0 0 0 2px ${c.color}`:"none",
              transition:"box-shadow .12s",
            }}/>
          ))}
        </div>
      </div>

      {/* Actions */}
      <div style={{display:"flex",gap:6}}>
        <button onClick={handleAdd} disabled={!label.trim()} style={{
          flex:1,padding:"7px",borderRadius:9,border:"none",cursor:label.trim()?"pointer":"default",
          background:label.trim()?`linear-gradient(135deg,${C.teal},${C.tealD})`:"rgba(0,0,0,0.07)",
          color:label.trim()?"white":C.muted,fontSize:12,fontWeight:700,fontFamily:FONT,
        }}>Add to Library</button>
        <button onClick={onClose} style={{
          padding:"7px 12px",borderRadius:9,cursor:"pointer",
          border:`1.5px solid ${C.border}`,background:"white",
          color:C.muted,fontSize:12,fontFamily:FONT,
        }}>Cancel</button>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════
   TEACHER DASHBOARD
═══════════════════════════════════════ */
function TeacherDashboard({
  schedItems,currentIndex,tokenSettings,starsEarned,audio,
  onAddItem,onRemoveItem,onChangeDuration,onReorder,onReset,onOpenDisplay,onTokenChange,onLoadTemplate,
  teacherInfo,onTeacherChange,
}){
  const [search,setSearch]=useState("");
  const [showToken,setShowToken]=useState(false);
  const [showAudio,setShowAudio]=useState(false);
  const [showTemplates,setShowTemplates]=useState(false);
  const [showCreator,setShowCreator]=useState(false);
  const [customActivities,setCustomActivities]=useState(()=>load("cp_custom",[]));
  const [vol,setVolState]=useState(audio.getVol());
  const [soundOn,setSoundOn]=useState(audio.getOn());

  function saveCustom(list){ setCustomActivities(list); save("cp_custom",list); }
  function addCustomActivity(a){ saveCustom([...customActivities,a]); }
  function deleteCustomActivity(id){ saveCustom(customActivities.filter(a=>a.id!==id)); }

  const allActivities=[...customActivities,...ACTIVITIES];
  const filtered=search?allActivities.filter(a=>a.label.toLowerCase().includes(search.toLowerCase())):allActivities;
  const canOpen=schedItems.length>=1;

  return(
    <div style={{display:"flex",height:"100vh",background:C.bg,fontFamily:FONT,overflow:"hidden"}}>

      {/* ── LEFT: Library ── */}
      <div style={{width:268,background:C.surface,borderRight:`1.5px solid ${C.border}`,
        display:"flex",flexDirection:"column",flexShrink:0,overflow:"hidden"}}>
        {/* Logo */}
        <div style={{padding:"14px 16px 10px",borderBottom:`1px solid ${C.border}`,
          display:"flex",alignItems:"center",gap:10}}>
          <img src={LOGO_B64} alt="ClassPulse" style={{height:36,objectFit:"contain"}}/>
        </div>
        <div style={{padding:"10px 12px 6px",borderBottom:`1px solid ${C.border}`}}>
          <div style={{position:"relative"}}>
            <span style={{position:"absolute",left:9,top:"50%",transform:"translateY(-50%)",fontSize:12,color:C.muted}}>🔍</span>
            <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search activities…"
              style={{width:"100%",padding:"7px 10px 7px 28px",borderRadius:10,
                border:`1.5px solid ${C.border}`,background:C.bgAlt,fontSize:12,
                fontFamily:FONT,color:C.ink,outline:"none"}}/>
          </div>
        </div>

        {/* Activity grid */}
        <div style={{flex:1,overflowY:"auto",padding:"10px 10px 4px",
          display:"flex",flexDirection:"column",gap:0}}>

          {/* Custom activities section */}
          {customActivities.length>0&&!search&&(
            <div style={{marginBottom:8}}>
              <div style={{fontSize:10,fontWeight:800,color:C.teal,letterSpacing:"0.08em",
                padding:"4px 2px 6px",textTransform:"uppercase"}}>My Activities</div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:6}}>
                {customActivities.map((a,i)=>(
                  <div key={a.id} style={{position:"relative"}}>
                    <Chip activity={a} index={i}/>
                    <button
                      onClick={()=>deleteCustomActivity(a.id)}
                      title="Remove"
                      style={{
                        position:"absolute",top:-4,right:-4,
                        width:16,height:16,borderRadius:"50%",
                        background:C.warn,border:"none",cursor:"pointer",
                        color:"white",fontSize:9,fontWeight:900,
                        display:"flex",alignItems:"center",justifyContent:"center",
                        lineHeight:1,zIndex:10,
                      }}>✕</button>
                  </div>
                ))}
              </div>
              <div style={{height:1,background:C.border,margin:"10px 0 6px"}}/>
            </div>
          )}

          {/* Built-in activities */}
          {!search&&customActivities.length>0&&(
            <div style={{fontSize:10,fontWeight:800,color:C.muted,letterSpacing:"0.08em",
              padding:"0 2px 6px",textTransform:"uppercase"}}>Built-in</div>
          )}
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:6,alignContent:"start",paddingBottom:8}}>
            {filtered.filter(a=>!a.custom||search).map((a,i)=><Chip key={a.id} activity={a} index={i}/>)}
            {search&&filtered.filter(a=>a.custom).map((a,i)=>(
              <div key={a.id} style={{position:"relative"}}>
                <Chip activity={a} index={i}/>
                <button onClick={()=>deleteCustomActivity(a.id)} style={{
                  position:"absolute",top:-4,right:-4,width:16,height:16,borderRadius:"50%",
                  background:C.warn,border:"none",cursor:"pointer",color:"white",fontSize:9,
                  fontWeight:900,display:"flex",alignItems:"center",justifyContent:"center",zIndex:10,
                }}>✕</button>
              </div>
            ))}
            {!filtered.length&&<div style={{gridColumn:"1/-1",textAlign:"center",padding:"20px 0",color:C.muted,fontSize:12}}>No results</div>}
          </div>
        </div>

        {/* Create custom activity */}
        {showCreator?(
          <CustomActivityCreator
            onAdd={addCustomActivity}
            onClose={()=>setShowCreator(false)}/>
        ):(
          <button onClick={()=>setShowCreator(true)} style={{
            margin:"0 10px 12px",padding:"8px",borderRadius:10,cursor:"pointer",
            border:`1.5px dashed ${C.teal}88`,background:C.tealL,
            color:C.tealD,fontSize:12,fontWeight:700,fontFamily:FONT,
            display:"flex",alignItems:"center",justifyContent:"center",gap:6,
            transition:"all .15s",
          }}>
            <span style={{fontSize:16,lineHeight:1}}>＋</span> Create Activity
          </button>
        )}
      </div>

      {/* ── RIGHT ── */}
      <div style={{flex:1,display:"flex",flexDirection:"column",overflow:"hidden"}}>

        {/* Top bar */}
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",
          padding:"14px 24px 12px",borderBottom:`1.5px solid ${C.border}`,background:C.surface}}>

          {/* Row 1: title + teacher inputs (left) | panel toggles + reset (right) */}
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:10}}>
            <div style={{display:"flex",flexDirection:"column",gap:6}}>
              <div style={{fontSize:16,fontWeight:800,color:C.ink,letterSpacing:"-0.3px"}}>Today's Schedule</div>
              <div style={{display:"flex",gap:8,alignItems:"center"}}>
                <input
                  value={teacherInfo.name}
                  onChange={e=>onTeacherChange({...teacherInfo,name:e.target.value})}
                  placeholder="Teacher name…"
                  style={{
                    padding:"4px 10px",borderRadius:8,fontSize:12,fontWeight:600,
                    border:`1.5px solid ${C.border}`,background:C.bgAlt,
                    color:C.ink,outline:"none",fontFamily:FONT,width:150,
                  }}/>
                <input
                  value={teacherInfo.room}
                  onChange={e=>onTeacherChange({...teacherInfo,room:e.target.value})}
                  placeholder="Room #…"
                  style={{
                    padding:"4px 10px",borderRadius:8,fontSize:12,fontWeight:600,
                    border:`1.5px solid ${C.border}`,background:C.bgAlt,
                    color:C.ink,outline:"none",fontFamily:FONT,width:90,
                  }}/>
              </div>
            </div>

            {/* Panel toggles + reset + Open Display stacked on the right */}
            <div style={{display:"flex",flexDirection:"column",gap:8,alignItems:"flex-end"}}>
              <div style={{display:"flex",gap:8,alignItems:"center"}}>
                <button onClick={()=>{setShowTemplates(s=>!s);setShowToken(false);setShowAudio(false);}} style={{
                  padding:"7px 13px",borderRadius:10,cursor:"pointer",
                  border:`1.5px solid ${showTemplates?C.sky:C.border}`,
                  background:showTemplates?"#EEF7FF":"transparent",
                  color:showTemplates?C.skyD:C.muted,fontSize:12,fontWeight:700,fontFamily:FONT,
                }}>📋 Templates</button>
                <button onClick={()=>{setShowToken(s=>!s);setShowAudio(false);setShowTemplates(false);}} style={{
                  padding:"7px 13px",borderRadius:10,cursor:"pointer",
                  border:`1.5px solid ${showToken?C.gold:C.border}`,
                  background:showToken?C.goldL:"transparent",
                  color:showToken?C.goldD:C.muted,fontSize:12,fontWeight:700,fontFamily:FONT,
                }}>⭐ Token Board</button>
                <button onClick={()=>{setShowAudio(s=>!s);setShowToken(false);setShowTemplates(false);}} style={{
                  padding:"7px 13px",borderRadius:10,cursor:"pointer",
                  border:`1.5px solid ${showAudio?"#8B5CF6":C.border}`,
                  background:showAudio?C.purpleL:"transparent",
                  color:showAudio?C.purpleD:C.muted,fontSize:12,fontWeight:700,fontFamily:FONT,
                }}>🔊 Audio</button>
                <button onClick={onReset} style={{
                  padding:"7px 13px",borderRadius:10,cursor:"pointer",
                  border:`1.5px solid ${C.border}`,background:"transparent",
                  fontSize:12,fontWeight:600,color:C.muted,fontFamily:FONT,
                }}>↺ Reset</button>
              </div>
              <button onClick={onOpenDisplay} disabled={!canOpen} style={{
                padding:"9px 24px",borderRadius:10,border:"none",cursor:canOpen?"pointer":"default",
                background:canOpen?`linear-gradient(135deg,${C.teal},#3DBFAC)`:"rgba(0,0,0,0.08)",
                color:canOpen?"white":C.muted,fontSize:12,fontWeight:700,
                boxShadow:canOpen?`0 4px 14px ${C.teal}55`:"none",
                transition:"all .18s",fontFamily:FONT,alignSelf:"flex-end",
              }}>{canOpen?"Open Classroom Display →":"Add at least 1 activity"}</button>
            </div>
          </div>
        </div>

        {/* Templates panel */}
        {showTemplates&&(
          <TemplatesPanel
            schedItems={schedItems}
            onLoadTemplate={onLoadTemplate}
            onClose={()=>setShowTemplates(false)}/>
        )}

        {/* Token settings panel */}
        {showToken&&(
          <div style={{padding:"14px 24px",background:C.goldL,
            borderBottom:`1.5px solid ${C.gold}44`,
            display:"flex",gap:24,flexWrap:"wrap",alignItems:"flex-start",
            animation:"cpSlideDown .3s ease both"}}>
            <div>
              <div style={{fontSize:11,fontWeight:800,color:C.goldD,marginBottom:7}}>⭐ Stars for Reward</div>
              <div style={{display:"flex",gap:5}}>
                {[3,5,7,10].map(n=>(
                  <button key={n} onClick={()=>onTokenChange({...tokenSettings,goal:n})} style={{
                    padding:"5px 12px",borderRadius:14,cursor:"pointer",fontFamily:FONT,
                    border:`1.5px solid ${tokenSettings.goal===n?C.gold:C.border}`,
                    background:tokenSettings.goal===n?C.gold:"white",
                    color:tokenSettings.goal===n?"white":C.muted,fontSize:12,fontWeight:700,
                  }}>{n} ⭐</button>
                ))}
              </div>
            </div>
            <div style={{flex:1,minWidth:220}}>
              <div style={{fontSize:11,fontWeight:800,color:C.goldD,marginBottom:7}}>🎁 Class Reward</div>
              <div style={{display:"flex",gap:5,flexWrap:"wrap"}}>
                {["10 min Extra Recess","Free Choice Time","Dance Party 🎵","Movie Clip 🎬","Sit Anywhere Day","Extra Snack Time"].map(r=>(
                  <button key={r} onClick={()=>onTokenChange({...tokenSettings,reward:r})} style={{
                    padding:"5px 12px",borderRadius:14,cursor:"pointer",fontFamily:FONT,
                    border:`1.5px solid ${tokenSettings.reward===r?C.gold:C.border}`,
                    background:tokenSettings.reward===r?C.gold:"white",
                    color:tokenSettings.reward===r?"white":C.muted,fontSize:11,fontWeight:700,
                  }}>{r}</button>
                ))}
              </div>
              <div style={{display:"flex",gap:6,marginTop:6,alignItems:"center"}}>
                <span style={{fontSize:11,color:C.goldD,fontWeight:600}}>Custom:</span>
                <input value={tokenSettings.customReward||""}
                  onChange={e=>onTokenChange({...tokenSettings,customReward:e.target.value,reward:e.target.value||tokenSettings.reward})}
                  placeholder="Type a custom reward…"
                  style={{flex:1,padding:"5px 10px",borderRadius:10,border:`1.5px solid ${C.gold}66`,
                    background:"white",fontSize:11,fontFamily:FONT,outline:"none"}}/>
              </div>
            </div>
            <div>
              <div style={{fontSize:11,fontWeight:800,color:C.goldD,marginBottom:7}}>⏱ Transition Time</div>
              <DurationPicker
                totalSeconds={tokenSettings.transitionSecs||(tokenSettings.transitionMins||2)*60}
                onChange={secs=>onTokenChange({...tokenSettings,transitionSecs:secs,transitionMins:Math.ceil(secs/60)})}
                color={C.purple}
                light={C.purpleL}
              />
            </div>
            {/* Current stars */}
            <div style={{display:"flex",alignItems:"center",gap:6,padding:"6px 14px",
              borderRadius:14,background:"rgba(245,195,0,0.15)",border:`1px solid ${C.gold}55`}}>
              <span style={{fontSize:12,color:C.goldD,fontWeight:700}}>Today: {starsEarned}/{tokenSettings.goal} ⭐</span>
            </div>
          </div>
        )}

        {/* Audio panel */}
        {showAudio&&(
          <div style={{padding:"14px 24px",background:C.purpleL,
            borderBottom:`1.5px solid ${C.purple}44`,
            display:"flex",gap:24,flexWrap:"wrap",alignItems:"center",
            animation:"cpSlideDown .3s ease both"}}>
            <div style={{fontSize:11,fontWeight:800,color:C.purpleD}}>🔊 Audio Settings</div>
            <div style={{display:"flex",alignItems:"center",gap:10}}>
              <span style={{fontSize:12,color:C.purpleD,fontWeight:600}}>Sound:</span>
              <button onClick={()=>{const v=!soundOn;setSoundOn(v);audio.setOn(v);}} style={{
                padding:"5px 16px",borderRadius:14,cursor:"pointer",fontFamily:FONT,
                border:`1.5px solid ${soundOn?C.purple:C.border}`,
                background:soundOn?C.purple:"white",
                color:soundOn?"white":C.muted,fontSize:12,fontWeight:700,
              }}>{soundOn?"ON 🔊":"OFF 🔇"}</button>
            </div>
            <div style={{display:"flex",alignItems:"center",gap:10}}>
              <span style={{fontSize:12,color:C.purpleD,fontWeight:600}}>Volume:</span>
              <input type="range" min="0" max="1" step="0.05" value={vol}
                onChange={e=>{const v=parseFloat(e.target.value);setVolState(v);audio.setVol(v);}}
                style={{width:120}}/>
              <span style={{fontSize:12,color:C.purpleD,fontWeight:600}}>{Math.round(vol*100)}%</span>
            </div>
            <button onClick={()=>audio.chimeStar()} style={{
              padding:"5px 14px",borderRadius:14,cursor:"pointer",fontFamily:FONT,
              border:`1.5px solid ${C.purple}`,background:"white",
              color:C.purple,fontSize:12,fontWeight:700,
            }}>Test Chime ♪</button>
            <div style={{fontSize:11,color:C.purpleD,opacity:0.7}}>
              Soft calming tones play on transitions, star events, and rewards
            </div>
          </div>
        )}

        {/* Legend */}
        <div style={{display:"flex",gap:12,padding:"8px 24px",
          borderBottom:`1px solid ${C.border}`,background:C.surface,alignItems:"center"}}>
          {[{color:C.teal,label:"NOW"},{color:C.sun,label:"NEXT"},{color:C.sky,label:"THEN"}].map(m=>(
            <div key={m.label} style={{display:"flex",alignItems:"center",gap:5}}>
              <div style={{width:18,height:18,borderRadius:5,background:m.color,
                display:"flex",alignItems:"center",justifyContent:"center",
                fontSize:7,color:"white",fontWeight:900}}>{m.label[0]}</div>
              <span style={{fontSize:11,fontWeight:700,color:m.color}}>{m.label}</span>
            </div>
          ))}
          <div style={{marginLeft:"auto",fontSize:11,color:C.muted}}>
            {schedItems.length} activit{schedItems.length===1?"y":"ies"} · Drag rows to reorder
          </div>
        </div>

        {/* Schedule list */}
        <div style={{flex:1,overflowY:"auto",padding:"16px 24px 24px"}}>
          <ScheduleBuilder items={schedItems} currentIndex={currentIndex}
            onAddItem={onAddItem} onRemoveItem={onRemoveItem}
            onChangeDuration={onChangeDuration} onReorder={onReorder}/>
        </div>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════
   CLASSROOM DISPLAY
═══════════════════════════════════════ */
function ClassroomDisplay({schedItems,currentIndex,tokenSettings,starsEarned,audio,teacherInfo,onBack,onStartTransition}){
  const containerRef=useRef(null);
  const [isFullscreen,setIsFullscreen]=useState(false);
  const nowItem=schedItems[currentIndex]||null;
  const nextItem=schedItems[currentIndex+1]||null;
  const thenItem=schedItems[currentIndex+2]||null;
  const totalSecs=(nowItem?.totalSeconds)||0;
  const timer=useTimer(totalSecs);
  const firedRef=useRef(false);

  // Auto-start timer as soon as the activity has a duration
  useEffect(()=>{
    if(totalSecs>0){ timer.restart(); }
  },[currentIndex, totalSecs]);

  useEffect(()=>{firedRef.current=false;phaseRef.current="green";},[currentIndex]);
  useEffect(()=>{
    if(timer.done&&nextItem&&!firedRef.current){
      firedRef.current=true;
      audio.chimeTransition();
      setTimeout(()=>onStartTransition(),800);
    }
  },[timer.done]);

  // Phase-change chimes — soft tone when background shifts yellow or red
  const phaseRef=useRef("green");
  useEffect(()=>{
    if(!timer.running) return;
    if(timer.timerPhase==="yellow"&&phaseRef.current==="green") audio.chimeWarn();
    if(timer.timerPhase==="red"&&phaseRef.current==="yellow")   audio.chimeWarn();
    phaseRef.current=timer.timerPhase;
  },[timer.timerPhase]);

  function toggleFS(){
    if(!document.fullscreenElement){containerRef.current?.requestFullscreen?.();setIsFullscreen(true);}
    else{document.exitFullscreen?.();setIsFullscreen(false);}
  }

  const remaining=schedItems.length-currentIndex;

  return(
    <div ref={containerRef} style={{
      minHeight:"100vh",display:"flex",flexDirection:"column",fontFamily:FONT,
      position:"relative",overflow:"hidden",
      background:"linear-gradient(135deg,#FEFAF2 0%,#F0FAF7 40%,#EEF5FF 100%)",
      backgroundSize:"300% 300%",animation:"cpBgGlow 18s ease infinite",
    }}>
      {/* Ambient orbs */}
      {[{top:"-5%",left:"-3%",size:360,c:"rgba(46,158,143,0.06)"},{bottom:"-8%",right:"-4%",size:420,c:"rgba(233,160,32,0.06)"}].map((o,i)=>(
        <div key={i} style={{position:"absolute",width:o.size,height:o.size,borderRadius:"50%",
          background:`radial-gradient(circle,${o.c} 0%,transparent 70%)`,
          top:o.top,left:o.left,right:o.right,bottom:o.bottom,pointerEvents:"none"}}/>
      ))}

      {/* Top bar */}
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",
        padding:"12px 24px",position:"relative",zIndex:10}}>
        <button onClick={onBack} style={{
          padding:"7px 14px",borderRadius:12,cursor:"pointer",
          border:`1.5px solid ${C.border}`,background:"rgba(255,255,255,0.88)",
          backdropFilter:"blur(8px)",fontSize:12,fontWeight:700,color:C.muted,fontFamily:FONT,
        }}>← Back</button>
        <StarBar earned={starsEarned} goal={tokenSettings.goal} reward={tokenSettings.reward}/>
        <div style={{display:"flex",gap:8,alignItems:"center"}}>
          <div style={{padding:"7px 14px",borderRadius:12,
            background:"rgba(255,255,255,0.88)",backdropFilter:"blur(8px)",
            border:`1.5px solid ${C.border}`,fontSize:12,fontWeight:600,color:C.muted}}>
            {remaining} of {schedItems.length} remaining
          </div>
          <button onClick={toggleFS} style={{
            padding:"7px 14px",borderRadius:12,cursor:"pointer",
            border:`1.5px solid ${C.border}`,background:"rgba(255,255,255,0.88)",
            backdropFilter:"blur(8px)",fontSize:12,fontWeight:700,color:C.muted,fontFamily:FONT,
          }}>{isFullscreen?"Exit ⛶":"⛶ Fullscreen"}</button>
        </div>
      </div>

      {/* Main */}
      <div style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",
        justifyContent:"center",padding:"8px 40px 16px",gap:16}}>
        <div style={{textAlign:"center",animation:"cpSlideDown .6s ease both"}}>
          <div style={{fontFamily:SERIF,fontSize:48,fontWeight:300,color:C.ink,
            letterSpacing:"-2px",lineHeight:1,fontStyle:"italic"}}>Today's Flow</div>
          {(teacherInfo?.name||teacherInfo?.room)&&(
            <div style={{fontSize:13,color:C.muted,marginTop:6,letterSpacing:"0.06em",fontWeight:600}}>
              {[teacherInfo.name,teacherInfo.room?"Room "+teacherInfo.room:null].filter(Boolean).join(" · ")}
            </div>
          )}
        </div>

        <div style={{display:"flex",gap:18,width:"100%",maxWidth:1080,alignItems:"stretch"}}>
          <DisplayCard item={nowItem} role="now" timer={totalSecs>0?timer:null}/>
          <DisplayCard item={nextItem} role="next" timer={null}/>
          <DisplayCard item={thenItem} role="then" timer={null}/>
        </div>

        {/* Timer controls */}
        {nowItem&&totalSecs>0&&(
          <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:12,
            padding:"18px 28px",borderRadius:28,
            background:"rgba(255,255,255,0.86)",backdropFilter:"blur(16px)",
            border:`1.5px solid ${C.border}`,
            boxShadow:"0 8px 32px rgba(0,0,0,0.07)",
            animation:"cpSlideUp .5s ease .2s both",width:"100%",maxWidth:420}}>
            <Ring
              prog={timer.prog}
              color={timer.done?C.sage:timer.timerPhase==="red"?C.warn:timer.timerPhase==="yellow"?C.sun:C.teal}
              size={140} sw={9} bg="rgba(0,0,0,0.07)">
              <div style={{fontFamily:SERIF,fontSize:timer.done?32:38,fontWeight:600,
                color:timer.done?C.sage:timer.timerPhase==="red"?C.warn:timer.timerPhase==="yellow"?C.sunD:C.ink,
                letterSpacing:"-2px",lineHeight:1,
                animation:timer.timerPhase==="red"&&!timer.done?"cpWarn 1s ease-in-out infinite":""}}>
                {timer.done?"🎉":fmt(timer.rem)}
              </div>
              <div style={{fontSize:10,color:C.muted,fontWeight:600,marginTop:2}}>
                {timer.done?"Done!":timer.running?"running":"paused"}
              </div>
            </Ring>

            <div style={{display:"flex",gap:10,alignItems:"center"}}>
              <button onClick={timer.reset} style={{
                width:40,height:40,borderRadius:"50%",cursor:"pointer",
                border:`1.5px solid ${C.border}`,background:C.surface,fontSize:16,
                display:"flex",alignItems:"center",justifyContent:"center",fontFamily:FONT,
                title:"Reset timer",
              }}>↺</button>

              {timer.done?(
                nextItem?(
                  <button onClick={onStartTransition} style={{
                    padding:"0 28px",height:46,borderRadius:23,border:"none",cursor:"pointer",
                    background:`linear-gradient(135deg,${C.purple},${C.purpleD})`,
                    color:"white",fontSize:14,fontWeight:800,fontFamily:FONT,
                    boxShadow:`0 6px 20px ${C.purple}55`,
                    display:"flex",alignItems:"center",gap:8,
                  }}>🔀 Start Transition</button>
                ):(
                  <div style={{fontSize:13,fontWeight:700,color:C.sage,padding:"0 12px"}}>🎊 All activities complete!</div>
                )
              ):timer.running?(
                <button onClick={timer.pause} style={{
                  padding:"0 28px",height:46,borderRadius:23,border:"none",cursor:"pointer",
                  background:`linear-gradient(135deg,${C.muted},#5A5550)`,
                  color:"white",fontSize:14,fontWeight:800,fontFamily:FONT,
                }}>⏸ Pause</button>
              ):(
                /* Paused — show Resume */
                <button onClick={timer.start} style={{
                  padding:"0 28px",height:46,borderRadius:23,border:"none",cursor:"pointer",
                  background:`linear-gradient(135deg,${C.teal},${C.tealD})`,
                  color:"white",fontSize:14,fontWeight:800,fontFamily:FONT,
                  boxShadow:`0 6px 20px ${C.teal}55`,
                }}>▶ Resume</button>
              )}

              {!timer.done&&nextItem&&(
                <button onClick={onStartTransition} title="Trigger transition now" style={{
                  width:40,height:40,borderRadius:"50%",cursor:"pointer",
                  border:`1.5px solid ${C.purple}55`,background:C.purpleL,fontSize:14,
                  display:"flex",alignItems:"center",justifyContent:"center",fontFamily:FONT,
                }}>🔀</button>
              )}
            </div>
            <div style={{fontSize:11,color:C.muted,fontWeight:500}}>
              {nowItem.activity.emoji} {nowItem.activity.label} · {nowItem.totalSeconds%60>0
                ?`${Math.floor(nowItem.totalSeconds/60)}m ${nowItem.totalSeconds%60}s`
                :`${Math.floor(nowItem.totalSeconds/60)}m`}
            </div>
          </div>
        )}

        {nowItem&&!totalSecs&&nextItem&&(
          <button onClick={onStartTransition} style={{
            padding:"12px 28px",borderRadius:20,border:"none",cursor:"pointer",
            background:`linear-gradient(135deg,${C.purple},${C.purpleD})`,
            color:"white",fontSize:14,fontWeight:800,fontFamily:FONT,
            boxShadow:`0 6px 20px ${C.purple}55`,
          }}>🔀 Start Transition to {nextItem.activity.label}</button>
        )}

        {!nowItem&&(
          <div style={{padding:"24px 40px",borderRadius:24,
            background:"rgba(255,255,255,0.9)",border:`2px solid ${C.teal}44`,textAlign:"center"}}>
            <div style={{fontSize:48,marginBottom:8}}>🎊</div>
            <div style={{fontFamily:SERIF,fontSize:28,color:C.teal,letterSpacing:"-0.5px"}}>Day Complete!</div>
            <div style={{fontSize:14,color:C.muted,marginTop:6}}>All activities finished. Wonderful work! 🌟</div>
          </div>
        )}
      </div>

      <div style={{textAlign:"center",padding:"0 0 14px",fontSize:13,color:C.muted,fontWeight:500,fontStyle:"italic"}}>
        Breathe. Follow the flow. 🌿
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════
   TRANSITION SCREEN
═══════════════════════════════════════ */
const TRANS_MSGS=["Time to switch! You've got this! 🌟","Let's move to the next activity! 🚀","Show me your best transition! 💪","Smooth moves, superstars! 🌈"];
const PRAISE_MSGS=["AMAZING TRANSITION! 🎉","YOU DID IT! SUPERSTAR! ⭐","WOW! SO SMOOTH! 🌟","FANTASTIC WORK! 💫","INCREDIBLE CLASS! 🏆"];

function TransitionScreen({fromItem,toItem,transitionSecs,onAwardStar,onNoStar,audio}){
  const totalSecs=transitionSecs||120;
  const timer=useTimer(totalSecs);
  const [msg]=useState(()=>rand(TRANS_MSGS));
  const [phase,setPhase]=useState("countdown");
  const chimeFiredRef=useRef(false);

  useEffect(()=>{timer.start();},[]);
  useEffect(()=>{
    if(timer.done&&phase==="countdown"){
      if(!chimeFiredRef.current){chimeFiredRef.current=true;audio.chimeTransition();}
      setTimeout(()=>setPhase("judge"),600);
    }
  },[timer.done]);

  // Full-page background shifts green → yellow → red as transition time runs down
  const transBg = timer.done || phase==="judge"
    ? "linear-gradient(145deg,#F0FFF8,#E8FFF2)"
    : timer.timerPhase==="red"
    ? "linear-gradient(145deg,#FFF0F0,#FFE0E0,#FFF5F5)"
    : timer.timerPhase==="yellow"
    ? "linear-gradient(145deg,#FFFBEA,#FFF3C0,#FFFDF0)"
    : "linear-gradient(145deg,#F0FFF8,#E4F9EE,#F5FFFA)";

  return(
    <div style={{
      minHeight:"100vh",display:"flex",flexDirection:"column",
      alignItems:"center",justifyContent:"center",fontFamily:FONT,
      background:transBg,
      position:"relative",overflow:"hidden",
      transition:"background 1.6s ease",
    }}>
      <div style={{position:"absolute",top:"-10%",left:"-5%",width:400,height:400,borderRadius:"50%",
        background:`radial-gradient(circle,${
          timer.timerPhase==="red"?"rgba(224,80,80,0.10)":
          timer.timerPhase==="yellow"?"rgba(233,160,32,0.10)":
          "rgba(78,148,96,0.10)"
        } 0%,transparent 70%)`,transition:"background 1.6s ease"}}/>
      <div style={{position:"absolute",bottom:"-10%",right:"-5%",width:360,height:360,borderRadius:"50%",
        background:`radial-gradient(circle,${
          timer.timerPhase==="red"?"rgba(224,80,80,0.08)":
          timer.timerPhase==="yellow"?"rgba(233,160,32,0.08)":
          "rgba(78,148,96,0.08)"
        } 0%,transparent 70%)`,transition:"background 1.6s ease"}}/>

      <div style={{textAlign:"center",display:"flex",flexDirection:"column",alignItems:"center",
        gap:18,animation:"cpSlideUp .5s ease both",padding:"0 40px",position:"relative",zIndex:1}}>

        <div style={{fontSize:12,fontWeight:800,letterSpacing:"0.14em",textTransform:"uppercase",
          color:C.purple,background:C.purpleL,padding:"4px 18px",
          borderRadius:20,border:`1px solid ${C.purple}33`}}>Transition Time</div>

        {/* Activity arrow */}
        <div style={{display:"flex",alignItems:"center",gap:18}}>
          <div style={{padding:"14px 20px",borderRadius:18,background:fromItem?.activity.light,
            border:`2px solid ${fromItem?.activity.color}44`,textAlign:"center"}}>
            <div style={{fontSize:36}}>{fromItem?.activity.emoji}</div>
            <div style={{fontSize:13,fontWeight:800,color:C.ink,marginTop:5}}>{fromItem?.activity.label}</div>
          </div>
          <div style={{fontSize:28,animation:"cpSwing 1.4s ease-in-out infinite",display:"inline-block"}}>→</div>
          <div style={{padding:"14px 20px",borderRadius:18,background:toItem?.activity.light,
            border:`2px solid ${toItem?.activity.color}44`,textAlign:"center"}}>
            <div style={{fontSize:36}}>{toItem?.activity.emoji}</div>
            <div style={{fontSize:13,fontWeight:800,color:C.ink,marginTop:5}}>{toItem?.activity.label}</div>
          </div>
        </div>

        <div style={{fontFamily:SERIF,fontSize:26,fontStyle:"italic",color:C.ink,maxWidth:460,lineHeight:1.3}}>
          {msg}
        </div>

        <Ring prog={timer.prog}
          color={timer.done?C.sage:timer.timerPhase==="red"?C.warn:timer.timerPhase==="yellow"?C.sun:C.sage}
          size={320} sw={18} bg="rgba(0,0,0,0.07)">
          <div style={{fontFamily:SERIF,fontSize:timer.done?64:86,fontWeight:600,
            color:timer.done?C.sage:timer.timerPhase==="red"?C.warn:timer.timerPhase==="yellow"?C.sunD:C.sageD||C.tealD,
            letterSpacing:"-4px",lineHeight:1,
            animation:timer.timerPhase==="red"&&!timer.done?"cpWarn 1s ease-in-out infinite":""}}>
            {timer.done?"✓":fmt(timer.rem)}
          </div>
          <div style={{fontSize:14,color:C.muted,fontWeight:700,marginTop:6,letterSpacing:"0.04em"}}>
            {timer.done?"transition done!":timer.running?"transitioning…":"ready"}
          </div>
        </Ring>

        {/* Checklist */}
        <div style={{display:"flex",gap:14,flexWrap:"wrap",justifyContent:"center"}}>
          {[{e:"🤫",l:"Quiet voices"},{e:"🧹",l:"Clean up"},{e:"📚",l:"Get next activity out"}].map((item,i)=>(
            <div key={i} style={{
              display:"flex",alignItems:"center",gap:8,
              padding:"10px 20px",borderRadius:14,
              background:"rgba(255,255,255,0.88)",border:`1.5px solid ${C.border}`,
              fontSize:15,fontWeight:700,color:C.ink,
              animation:`cpPop .4s ease ${i*0.1}s both`,
            }}>
              <span style={{fontSize:22}}>{item.e}</span>{item.l}
            </div>
          ))}
        </div>

        {/* Controls */}
        {phase==="countdown"?(
          <div style={{display:"flex",gap:10}}>
            {!timer.running&&!timer.done&&(
              <button onClick={timer.start} style={{
                padding:"11px 26px",borderRadius:20,border:"none",cursor:"pointer",
                background:`linear-gradient(135deg,${C.purple},${C.purpleD})`,
                color:"white",fontSize:14,fontWeight:800,fontFamily:FONT,
                boxShadow:`0 6px 20px ${C.purple}55`,
              }}>▶ Start</button>
            )}
            {timer.running&&(
              <button onClick={timer.pause} style={{
                padding:"11px 22px",borderRadius:20,border:"none",cursor:"pointer",
                background:`linear-gradient(135deg,${C.muted},#5A5550)`,
                color:"white",fontSize:14,fontWeight:800,fontFamily:FONT,
              }}>⏸ Pause</button>
            )}
            <button onClick={()=>setPhase("judge")} style={{
              padding:"11px 22px",borderRadius:20,cursor:"pointer",
              border:`1.5px solid ${C.border}`,background:"rgba(255,255,255,0.9)",
              color:C.muted,fontSize:13,fontWeight:700,fontFamily:FONT,
            }}>Skip to Decision</button>
          </div>
        ):(
          /* JUDGE PHASE */
          <div style={{
            display:"flex",flexDirection:"column",alignItems:"center",gap:16,
            padding:"28px 36px",borderRadius:28,
            background:"rgba(255,255,255,0.95)",backdropFilter:"blur(12px)",
            border:`1.5px solid ${C.border}`,boxShadow:"0 8px 32px rgba(0,0,0,0.08)",
            animation:"cpPop .4s ease both",marginTop:4,
          }}>
            <div style={{fontSize:18,fontWeight:900,color:C.ink}}>
              How did the transition go? 👀
            </div>
            <div style={{fontSize:13,color:C.muted,fontWeight:600}}>
              Teacher/staff decision — did the class earn a star?
            </div>
            <div style={{display:"flex",gap:14}}>
              <button onClick={onAwardStar} style={{
                padding:"14px 32px",borderRadius:22,border:"none",cursor:"pointer",
                background:`linear-gradient(135deg,${C.gold},#F0A500)`,
                color:"white",fontSize:15,fontWeight:900,fontFamily:FONT,
                boxShadow:`0 8px 24px ${C.gold}66`,
                display:"flex",flexDirection:"column",alignItems:"center",gap:4,
              }}>
                <span style={{fontSize:28}}>⭐</span>
                Yes! Award a Star
              </button>
              <button onClick={onNoStar} style={{
                padding:"14px 28px",borderRadius:22,cursor:"pointer",
                border:`2px solid ${C.border}`,background:"rgba(255,255,255,0.9)",
                color:C.muted,fontSize:15,fontWeight:700,fontFamily:FONT,
                display:"flex",flexDirection:"column",alignItems:"center",gap:4,
              }}>
                <span style={{fontSize:28}}>🔄</span>
                Not this time
              </button>
            </div>
            <div style={{fontSize:11,color:C.muted,textAlign:"center",maxWidth:300}}>
              Stars are only awarded for smooth, calm, on-time transitions. You decide!
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════
   STAR CELEBRATION
   Phase 1 → flying star spins in (1.2s)
   Phase 2 → lands on chart slot (0.8s)
   Phase 3 → full chart + praise visible (auto-continue after 5s)
═══════════════════════════════════════ */
function StarCelebration({starsEarned,goal,reward,toItem,onContinue,audio}){
  const [praise]         = useState(()=>rand(PRAISE_MSGS));
  const [phase, setPhase]= useState(0); // 0=flying 1=landing 2=settled
  const autoRef          = useRef(null);

  useEffect(()=>{
    audio.chimeStar();
    // phase 0→1 after star finishes flying
    const t1=setTimeout(()=>setPhase(1), 1200);
    // phase 1→2 after land thud
    const t2=setTimeout(()=>setPhase(2), 2100);
    // auto-continue
    autoRef.current=setTimeout(onContinue, 6500);
    return()=>{clearTimeout(t1);clearTimeout(t2);clearTimeout(autoRef.current);};
  },[]);

  // star slot positions — compute rough x offset for new star
  // chart holds `goal` slots; newStarIndex = starsEarned-1
  const newStarIdx = starsEarned - 1;

  return(
    <div style={{
      minHeight:"100vh",
      display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",
      background:"linear-gradient(145deg,#FFFBEA,#FFF8F0,#FEFCF0)",
      position:"relative",overflow:"hidden",fontFamily:FONT,
    }}>
      <Confetti/>

      {/* Warm ambient glow */}
      <div style={{position:"absolute",inset:0,
        background:"radial-gradient(ellipse 80% 60% at 50% 40%, rgba(245,195,0,0.10) 0%, transparent 70%)",
        pointerEvents:"none"}}/>

      {/* ── FLYING STAR (phase 0 & 1) ── */}
      {phase < 2 && (
        <div style={{
          position:"fixed",
          // starts top-center, flies down to chart
          top: phase===0 ? "8vh" : "54vh",
          left:"50%",
          transform:`translateX(-50%) rotate(${phase===0?"0deg":"720deg"}) scale(${phase===0?1.4:1})`,
          transition: phase===0
            ? "top 1.1s cubic-bezier(.22,1,.36,1), transform 1.1s cubic-bezier(.22,1,.36,1)"
            : "top 0.55s cubic-bezier(.34,1.56,.64,1), transform 0.55s ease",
          fontSize: phase===0 ? 100 : 68,
          lineHeight:1,
          zIndex:100,
          filter:`drop-shadow(0 0 ${phase===0?32:20}px #F5C300BB)`,
          pointerEvents:"none",
        }}>⭐</div>
      )}

      {/* ── MAIN CONTENT ── */}
      <div style={{
        position:"relative",zIndex:1,
        display:"flex",flexDirection:"column",alignItems:"center",
        gap:20,padding:"0 40px",width:"100%",maxWidth:680,
        opacity: phase>=1 ? 1 : 0,
        transform: phase>=1 ? "translateY(0)" : "translateY(20px)",
        transition:"opacity 0.5s ease, transform 0.5s ease",
      }}>

        {/* Praise message */}
        <div style={{
          fontFamily:SERIF,fontSize:44,fontStyle:"italic",fontWeight:600,
          color:C.goldD,letterSpacing:"-1.5px",lineHeight:1.1,textAlign:"center",
          animation: phase>=2 ? "cpSlideUp .4s ease both" : "none",
        }}>{praise}</div>

        {/* ── STAR CHART ── */}
        <div style={{
          width:"100%",background:"rgba(255,255,255,0.88)",
          backdropFilter:"blur(12px)",
          border:`2.5px solid ${C.gold}66`,
          borderRadius:28,padding:"22px 28px 18px",
          boxShadow:`0 12px 40px ${C.gold}33`,
          animation: phase>=1 ? "cpPop .45s ease both" : "none",
        }}>
          {/* Chart header */}
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:16}}>
            <div style={{fontFamily:SERIF,fontSize:20,color:C.ink,letterSpacing:"-0.5px",fontWeight:600}}>
              Class Star Chart ✨
            </div>
            <div style={{
              fontSize:13,fontWeight:800,color:C.goldD,
              background:C.goldL,padding:"4px 14px",
              borderRadius:20,border:`1.5px solid ${C.gold}55`,
            }}>
              {starsEarned} / {goal} Stars
            </div>
          </div>

          {/* Star slots row */}
          <div style={{
            display:"flex",gap:8,justifyContent:"center",
            flexWrap:"wrap",marginBottom:18,
          }}>
            {Array.from({length:goal},(_,i)=>{
              const earned  = i < starsEarned;
              const isNew   = i === newStarIdx && phase >= 1;
              return(
                <div key={i} style={{
                  width:52,height:52,borderRadius:14,
                  background: earned ? C.goldL : "rgba(0,0,0,0.04)",
                  border:`2px solid ${earned ? C.gold+"88" : C.border}`,
                  display:"flex",alignItems:"center",justifyContent:"center",
                  fontSize: earned ? 28 : 20,
                  transition:"all 0.3s ease",
                  transform: isNew && phase===1 ? "scale(1.35)" : earned ? "scale(1)" : "scale(0.95)",
                  boxShadow: isNew && phase>=1
                    ? `0 0 20px ${C.gold}99, 0 0 6px ${C.gold}`
                    : earned ? `0 2px 8px ${C.gold}44` : "none",
                  animation: isNew && phase>=1 ? "cpStarLand 0.55s cubic-bezier(.34,1.56,.64,1) both" : "none",
                }}>
                  {earned ? "⭐" : <span style={{opacity:0.25,fontSize:16}}>☆</span>}
                </div>
              );
            })}
          </div>

          {/* Progress bar */}
          <div style={{height:10,background:"rgba(0,0,0,0.06)",borderRadius:5,overflow:"hidden",marginBottom:10}}>
            <div style={{
              height:"100%",
              width:`${(starsEarned/goal)*100}%`,
              background:`linear-gradient(90deg,${C.sun},${C.gold})`,
              borderRadius:5,
              transition:"width 0.8s cubic-bezier(.22,1,.36,1)",
              boxShadow:`0 0 10px ${C.gold}88`,
            }}/>
          </div>

          {/* Reward label */}
          <div style={{
            display:"flex",alignItems:"center",justifyContent:"center",gap:10,
            padding:"12px 18px",borderRadius:16,
            background:`linear-gradient(135deg,${C.goldL},#FFF3C0)`,
            border:`2px solid ${C.gold}55`,
          }}>
            <span style={{fontSize:20}}>🎁</span>
            <div style={{textAlign:"center"}}>
              <div style={{fontSize:10,fontWeight:800,letterSpacing:"0.1em",
                textTransform:"uppercase",color:C.goldD,opacity:0.7}}>
                Class Reward Goal
              </div>
              <div style={{fontSize:16,fontWeight:800,color:C.goldD,marginTop:1}}>
                {reward}
              </div>
            </div>
            {starsEarned>=goal && (
              <div style={{
                marginLeft:8,fontSize:12,fontWeight:800,color:"white",
                background:C.sage,padding:"4px 12px",borderRadius:20,
              }}>EARNED! 🏆</div>
            )}
          </div>
        </div>

        {/* Next activity hint */}
        {toItem&&(
          <div style={{
            display:"flex",alignItems:"center",gap:12,
            padding:"12px 22px",borderRadius:18,
            background:"rgba(255,255,255,0.82)",border:`1.5px solid ${C.border}`,
            fontSize:14,fontWeight:600,color:C.ink,
            animation: phase>=2 ? "cpSlideUp .5s ease .1s both" : "none",
            opacity: phase>=2 ? 1:0,
          }}>
            <span style={{fontSize:24}}>{toItem.activity.emoji}</span>
            <span>Next up: <strong>{toItem.activity.label}</strong></span>
            <span style={{fontSize:11,color:C.muted,marginLeft:4}}>— timer starts automatically</span>
          </div>
        )}

        {/* Continue button + auto-countdown */}
        <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:8,
          animation: phase>=2 ? "cpSlideUp .5s ease .2s both" : "none",
          opacity: phase>=2 ? 1:0,
        }}>
          <button onClick={()=>{clearTimeout(autoRef.current);onContinue();}} style={{
            padding:"12px 36px",borderRadius:20,border:"none",cursor:"pointer",
            background:`linear-gradient(135deg,${C.teal},${C.tealD})`,
            color:"white",fontSize:14,fontWeight:800,fontFamily:FONT,
            boxShadow:`0 6px 20px ${C.teal}55`,
          }}>Continue →</button>
          <div style={{fontSize:11,color:C.muted,fontWeight:500}}>
            Continuing automatically in a few seconds…
          </div>
        </div>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════
   REWARD SCREEN
═══════════════════════════════════════ */
function RewardScreen({stars,reward,onDone,audio}){
  const [confetti,setConfetti]=useState(true);
  useEffect(()=>{audio.chimeReward();const t=setTimeout(()=>setConfetti(false),5500);return()=>clearTimeout(t);},[]);
  return(
    <div style={{minHeight:"100vh",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",
      position:"relative",overflow:"hidden",fontFamily:FONT}}>
      {confetti&&<Confetti/>}
      <div style={{
        position:"absolute",inset:0,
        background:"linear-gradient(270deg,#FFD700,#FF8C42,#FF6B9D,#C084FC,#60A5FA,#34D399,#FFD700)",
        backgroundSize:"400% 400%",opacity:0.1,animation:"cpRainbow 4s linear infinite",
      }}/>
      <div style={{position:"absolute",inset:0,background:"linear-gradient(145deg,#FFFBEA,#FFF8F0,#FEFCF0)"}}/>
      <div style={{position:"relative",zIndex:1,textAlign:"center",display:"flex",flexDirection:"column",
        alignItems:"center",gap:20,animation:"cpSlideUp .6s ease both",padding:"0 40px"}}>
        <div style={{fontSize:84,animation:"cpPulseBig 2s ease-in-out infinite",
          filter:"drop-shadow(0 0 24px #F5C30099)"}}>🏆</div>
        <div style={{fontFamily:SERIF,fontSize:56,fontStyle:"italic",fontWeight:600,
          color:C.goldD,letterSpacing:"-2px",lineHeight:1}}>We Did It!</div>
        <div style={{display:"flex",gap:6,justifyContent:"center",flexWrap:"wrap"}}>
          {Array.from({length:stars},(_,i)=>(
            <div key={i} style={{fontSize:34,animation:`cpStarPop .5s ease ${i*0.1}s both`,
              filter:"drop-shadow(0 0 6px #F5C30088)"}}>⭐</div>
          ))}
        </div>
        <div style={{fontSize:20,fontWeight:700,color:C.ink,
          background:"rgba(255,255,255,0.9)",border:`2px solid ${C.gold}55`,
          borderRadius:18,padding:"12px 28px",boxShadow:`0 4px 20px ${C.gold}33`}}>
          🎉 Class Reward: <span style={{color:C.goldD}}>{reward}</span>
        </div>
        <div style={{fontSize:15,color:C.muted,fontWeight:600,maxWidth:400,lineHeight:1.6}}>
          All {stars} stars earned through amazing transitions today! 🌈
        </div>
        <button onClick={onDone} style={{
          padding:"14px 36px",borderRadius:22,border:"none",cursor:"pointer",
          background:`linear-gradient(135deg,${C.teal},${C.tealD})`,
          color:"white",fontSize:15,fontWeight:800,fontFamily:FONT,
          boxShadow:`0 8px 28px ${C.teal}55`,marginTop:6,
        }}>Start a New Day ✨</button>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════
   GLOBAL CSS
═══════════════════════════════════════ */
const CSS=`
  @import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,300;0,9..144,400;0,9..144,600;1,9..144,400&family=Nunito:wght@400;500;600;700;800;900&display=swap');
  *,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
  html,body{height:100%;font-family:${FONT};background:${C.bg};color:${C.ink}}
  button{cursor:pointer;font-family:${FONT}}
  ::-webkit-scrollbar{width:6px}
  ::-webkit-scrollbar-thumb{background:rgba(0,0,0,0.12);border-radius:4px}
  @keyframes cpBgGlow{0%,100%{background-position:0% 50%}50%{background-position:100% 50%}}
  @keyframes cpSlideUp{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:translateY(0)}}
  @keyframes cpSlideDown{from{opacity:0;transform:translateY(-12px)}to{opacity:1;transform:translateY(0)}}
  @keyframes cpPop{0%{transform:scale(0.82);opacity:0}65%{transform:scale(1.06)}100%{transform:scale(1);opacity:1}}
  @keyframes cpBreathe{0%,100%{transform:scale(1);opacity:.85}50%{transform:scale(1.1);opacity:1}}
  @keyframes cpBounce{0%{transform:scale(1)}30%{transform:scale(1.18)}60%{transform:scale(.94)}100%{transform:scale(1)}}
  @keyframes cpWarn{0%,100%{opacity:1}50%{opacity:.4}}
  @keyframes cpStarPop{0%{transform:scale(0) rotate(-30deg);opacity:0}60%{transform:scale(1.3) rotate(8deg)}100%{transform:scale(1) rotate(0);opacity:1}}
  @keyframes cpStarLand{0%{transform:scale(2.2) rotate(-180deg);opacity:0}60%{transform:scale(1.4) rotate(10deg)}100%{transform:scale(1) rotate(0);opacity:1}}
  @keyframes cpStarOrbit{0%{transform:translateY(0) rotate(0)}25%{transform:translateY(-12px) rotate(90deg)}50%{transform:translateY(0) rotate(180deg)}75%{transform:translateY(12px) rotate(270deg)}100%{transform:translateY(0) rotate(360deg)}}
  @keyframes cpConfetti{0%{transform:translateY(-20px) rotate(0);opacity:1}100%{transform:translateY(110vh) rotate(720deg);opacity:0}}
  @keyframes cpRainbow{0%{background-position:0% 50%}100%{background-position:200% 50%}}
  @keyframes cpPulseBig{0%,100%{transform:scale(1)}50%{transform:scale(1.07)}}
  @keyframes cpSwing{0%,100%{transform:rotate(-10deg)}50%{transform:rotate(10deg)}}
`;

/* ═══════════════════════════════════════
   ROOT APP
═══════════════════════════════════════ */
export default function ClassPulse(){
  const audio=useAudio();

  // Persisted state
  const [schedItems,setSchedItems]=useState(()=>load("cp_sched",[]));
  const [currentIndex,setCurrentIndex]=useState(()=>load("cp_idx",0));
  const [starsEarned,setStarsEarned]=useState(()=>load("cp_stars",0));
  const [tokenSettings,setTokenSettings]=useState(()=>load("cp_token",{
    goal:5,reward:"10 min Extra Recess",transitionMins:2,customReward:"",
  }));

  const [teacherInfo,setTeacherInfo]=useState(()=>load("cp_teacher",{name:"",room:""}));
  useEffect(()=>save("cp_teacher",teacherInfo),[teacherInfo]);

  // Views
  const [view,setView]=useState("dashboard");
  const [pendingNextIndex,setPendingNextIndex]=useState(null);

  // Persist on changes
  useEffect(()=>save("cp_sched",schedItems),[schedItems]);
  useEffect(()=>save("cp_idx",currentIndex),[currentIndex]);
  useEffect(()=>save("cp_stars",starsEarned),[starsEarned]);
  useEffect(()=>save("cp_token",tokenSettings),[tokenSettings]);

  // Schedule management
  function addItem(activity,insertIndex){
    const newItem={uid:uid(),activity,totalSeconds:null};
    setSchedItems(prev=>{const n=[...prev];n.splice(insertIndex,0,newItem);return n;});
  }
  function removeItem(itemUid){setSchedItems(prev=>prev.filter(i=>i.uid!==itemUid));}
  function changeDuration(itemUid,secs){setSchedItems(prev=>prev.map(i=>i.uid===itemUid?{...i,totalSeconds:secs}:i));}
  function reorderItems(fromIdx,toIdx){
    setSchedItems(prev=>{
      const n=[...prev];const[moved]=n.splice(fromIdx,1);
      const insertAt=toIdx>fromIdx?toIdx-1:toIdx;
      n.splice(insertAt,0,moved);return n;
    });
  }
  function reset(){
    setSchedItems([]);setCurrentIndex(0);setStarsEarned(0);
    setPendingNextIndex(null);setView("dashboard");
    save("cp_sched",[]);save("cp_idx",0);save("cp_stars",0);
  }
  function loadTemplate(items){
    setSchedItems(items);
    setCurrentIndex(0);setStarsEarned(0);setPendingNextIndex(null);
    save("cp_sched",items);save("cp_idx",0);save("cp_stars",0);
  }

  // Transition flow
  function startTransition(){
    const nextIdx=currentIndex+1;
    if(nextIdx<schedItems.length){setPendingNextIndex(nextIdx);setView("transition");}
  }
  function handleAwardStar(){
    const newStars=starsEarned+1;
    setStarsEarned(newStars);
    setCurrentIndex(pendingNextIndex);
    setPendingNextIndex(null);
    if(newStars>=tokenSettings.goal) setView("reward");
    else setView("star");
  }
  function handleNoStar(){setCurrentIndex(pendingNextIndex);setPendingNextIndex(null);setView("display");}
  function handleStarContinue(){setView("display");}

  const fromItem=schedItems[currentIndex]||null;
  const toItem=schedItems[pendingNextIndex??(currentIndex+1)]||null;

  return(
    <>
      <style>{CSS}</style>
      {view==="dashboard"&&(
        <TeacherDashboard
          schedItems={schedItems} currentIndex={currentIndex}
          tokenSettings={tokenSettings} starsEarned={starsEarned} audio={audio}
          onAddItem={addItem} onRemoveItem={removeItem}
          onChangeDuration={changeDuration} onReorder={reorderItems}
          onReset={reset}
          onOpenDisplay={()=>{setView("display");}}
          onTokenChange={setTokenSettings}
          onLoadTemplate={loadTemplate}
          teacherInfo={teacherInfo} onTeacherChange={setTeacherInfo}/>
      )}
      {view==="display"&&(
        <ClassroomDisplay
          schedItems={schedItems} currentIndex={currentIndex}
          tokenSettings={tokenSettings} starsEarned={starsEarned} audio={audio}
          teacherInfo={teacherInfo}
          onBack={()=>setView("dashboard")} onStartTransition={startTransition}/>
      )}
      {view==="transition"&&(
        <TransitionScreen
          fromItem={fromItem} toItem={schedItems[pendingNextIndex]||null}
          transitionSecs={tokenSettings.transitionSecs||(tokenSettings.transitionMins||2)*60}
          onAwardStar={handleAwardStar} onNoStar={handleNoStar} audio={audio}/>
      )}
      {view==="star"&&(
        <StarCelebration
          starsEarned={starsEarned} goal={tokenSettings.goal}
          reward={tokenSettings.reward}
          toItem={schedItems[currentIndex]||null}
          onContinue={handleStarContinue} audio={audio}/>
      )}
      {view==="reward"&&(
        <RewardScreen stars={starsEarned} reward={tokenSettings.reward} onDone={reset} audio={audio}/>
      )}
    </>
  );
}
